/**
 * global-aggregator.ts — 全局聚合器 (Phase 3.2)
 *
 * 接收联邦上报的脱敏统计，加权聚合，生成规则更新提案。
 */
import { createLogger } from '../../infra/logger';

const log = createLogger('diagnosis/global-aggregator');

// ═══ Types ═══

export interface RuleStat {
  ruleId: string;
  globalConfidence: number;
  orgCount: number;
  avgAdoptionRate: number;
  avgImprovementRate: number;
  recommendedThreshold: number;
}

export interface CandidateRule {
  patternSignature: string;
  globalConfidence: number;
  orgCount: number;
  avgLift: number;
  totalTriggerCount: number;
}

export interface AggregationResult {
  ruleStats: RuleStat[];
  candidateRules: CandidateRule[];
  generatedAt: string;
}

interface OrgReport {
  orgHash: string;
  diagnosisCount: number;
  triggerCounts: Record<string, number>;
  confidences: Record<string, number>;
  adoptionRates: Record<string, number>;
  improvementRates: Record<string, number>;
  thresholds: Record<string, number[]>;
  candidatePatterns: Array<{ signature: string; confidence: number; lift: number; triggerCount: number }>;
  qualityMetrics: Array<{ hypothesisConfirmRate: number; actionAdoptionRate: number }>;
}

// ═══ GlobalAggregator ═══

export class GlobalAggregator {
  private reports = new Map<string, OrgReport[]>(); // orgHash → reports (滑动窗口)

  /** 接收一份上报 */
  receiveReport(orgHash: string, report: OrgReport): void {
    let reports = this.reports.get(orgHash);
    if (!reports) { reports = []; this.reports.set(orgHash, reports); }
    reports.push(report);
    // 滑动窗口：只保留最近 N 次诊断
    const maxWindow = 4;
    if (reports.length > maxWindow) {
      reports.splice(0, reports.length - maxWindow);
    }
    log.info({ orgHash, totalReports: reports.length }, '上报已接收');
  }

  /** 全局聚合 */
  aggregate(): AggregationResult {
    const allOrgs = [...this.reports.entries()];
    if (allOrgs.length < 3) {
      log.warn({ orgCount: allOrgs.length }, '组织数不足 3——不生成提案');
      return { ruleStats: [], candidateRules: [], generatedAt: new Date().toISOString() };
    }

    const ruleStats = this.aggregateRuleStats(allOrgs);
    const candidateRules = this.aggregateCandidateRules(allOrgs);

    return { ruleStats, candidateRules, generatedAt: new Date().toISOString() };
  }

  private aggregateRuleStats(allOrgs: Array<[string, OrgReport[]]>): RuleStat[] {
    const ruleMap = new Map<string, {
      confidences: number[]; adoptionRates: number[]; improvementRates: number[];
      triggerCounts: number[]; thresholds: number[][]; orgCount: number;
    }>();

    for (const [, reports] of allOrgs) {
      // 只取最近一次上报（滑动窗口内最新）
      const latest = reports[reports.length - 1];
      for (const [ruleId, confidence] of Object.entries(latest.confidences || {})) {
        let entry = ruleMap.get(ruleId);
        if (!entry) {
          entry = { confidences: [], adoptionRates: [], improvementRates: [], triggerCounts: [], thresholds: [], orgCount: 0 };
          ruleMap.set(ruleId, entry);
        }
        entry.confidences.push(confidence);
        entry.adoptionRates.push(latest.adoptionRates?.[ruleId] || 0);
        entry.improvementRates.push(latest.improvementRates?.[ruleId] || 0);
        entry.triggerCounts.push(latest.triggerCounts?.[ruleId] || 0);
        entry.thresholds.push(latest.thresholds?.[ruleId] || []);
        entry.orgCount++;
      }
    }

    const stats: RuleStat[] = [];
    for (const [ruleId, entry] of ruleMap) {
      if (entry.orgCount < 3) continue; // min sample gate

      const totalTriggers = entry.triggerCounts.reduce((a, b) => a + b, 0);
      const weights = totalTriggers > 0
        ? entry.triggerCounts.map(t => t / totalTriggers)
        : entry.triggerCounts.map(() => 1 / entry.orgCount); // 等权 fallback

      if (totalTriggers === 0) {
        log.warn({ ruleId }, 'total_trigger_count 为 0——回退到等权平均');
      }

      const weightedConf = entry.confidences.reduce((sum, c, i) => sum + c * weights[i], 0);
      const avgAdoption = entry.adoptionRates.reduce((a, b) => a + b, 0) / entry.orgCount;
      const avgImprovement = entry.improvementRates.reduce((a, b) => a + b, 0) / entry.orgCount;
      const allThresholds = entry.thresholds.flat();
      const recThreshold = allThresholds.length > 0
        ? allThresholds.sort((a, b) => a - b)[Math.floor(allThresholds.length / 2)]
        : 0;

      stats.push({ ruleId, globalConfidence: Math.round(weightedConf * 1000) / 1000, orgCount: entry.orgCount, avgAdoptionRate: avgAdoption, avgImprovementRate: avgImprovement, recommendedThreshold: recThreshold });
    }
    return stats;
  }

  private aggregateCandidateRules(allOrgs: Array<[string, OrgReport[]]>): CandidateRule[] {
    const candMap = new Map<string, { confidences: number[]; lifts: number[]; triggerCounts: number[]; orgCount: number }>();

    for (const [, reports] of allOrgs) {
      const latest = reports[reports.length - 1];
      for (const cp of latest.candidatePatterns || []) {
        let entry = candMap.get(cp.signature);
        if (!entry) { entry = { confidences: [], lifts: [], triggerCounts: [], orgCount: 0 }; candMap.set(cp.signature, entry); }
        entry.confidences.push(cp.confidence);
        entry.lifts.push(cp.lift);
        entry.triggerCounts.push(cp.triggerCount);
        entry.orgCount++;
      }
    }

    const candidates: CandidateRule[] = [];
    for (const [signature, entry] of candMap) {
      if (entry.orgCount < 3) continue;
      const totalTriggers = entry.triggerCounts.reduce((a, b) => a + b, 0);
      if (totalTriggers < 10) continue; // 最小触发次数门禁

      const avgLift = entry.orgCount >= 5
        ? entry.lifts.sort((a, b) => a - b)[Math.floor(entry.lifts.length / 2)] // 中位数
        : entry.lifts.reduce((a, b) => a + b, 0) / entry.lifts.length; // 均值 + 标注

      candidates.push({
        patternSignature: signature,
        globalConfidence: entry.confidences.reduce((a, b) => a + b, 0) / entry.orgCount,
        orgCount: entry.orgCount, avgLift, totalTriggerCount: totalTriggers,
      });
    }
    return candidates;
  }
}
